#!/usr/bin/env python3
"""Export assets generated by the actual Mac app's isolated capture session."""
import base64
import json
from pathlib import Path
import subprocess
import shutil
import sys
import tempfile
import time

source_app = Path(sys.argv[1]).resolve()
# Keep a stable signed bundle: unrelated rebuilds must not replace code while
# ScreenCaptureKit is capturing its window.
app = Path(tempfile.gettempdir()) / "MoodMargins-StoreCapture" / "MoodMargins.app"
if app.exists():
    shutil.rmtree(app)
shutil.copytree(source_app, app, symlinks=True)
root = Path(sys.argv[2]).resolve()
stickers_only = '--stickers-only' in sys.argv
locales = [argument for argument in sys.argv[3:] if argument != '--stickers-only'] or ['en', 'es', 'ar']
sessions = [(language, dark) for language in locales for dark in ((False,) if stickers_only else (False, True))]
for language, dark in sessions:
    # Close only our explicit capture sessions, never someone's journal window.
    processes = subprocess.check_output(['ps', '-ax', '-o', 'pid=,command='], text=True)
    for row in processes.splitlines():
        parts = row.strip().split(None, 1)
        if len(parts) == 2 and '/Contents/MacOS/MoodMargins' in parts[1] and '--export-store-captures' in parts[1]:
            subprocess.run(['kill', '-TERM', parts[0]], check=False)
    log = Path(tempfile.gettempdir()) / f'MoodMargins-mac-{language}-{"dark" if dark else "light"}-assets.log'
    errors = log.with_suffix('.errors.log')
    log.write_text('')
    locale = {'en': 'en_US', 'es': 'es_ES', 'ar': 'ar_SA'}[language]
    subprocess.run(['open', '-n', '--stdout', str(log), '--stderr', str(errors), str(app), '--args', '--marketing-capture', '--export-store-captures', '-AppleLanguages', f'({language})', '-AppleLocale', locale] + (['--marketing-dark'] if dark else []) + (['--marketing-stickers-only'] if stickers_only else []), check=True)
    destination = root / language
    destination.mkdir(parents=True, exist_ok=True)
    required = {'mac-dark.png'} if dark else {f'mac-{name}.png' for name in ['today', 'pages', 'insights', 'stickers', 'customize', 'botanical', 'coastal', 'sunset']}
    if stickers_only:
        required = {'mac-stickers.png'}
    elif not dark:
        required.add('mac-preview-raw.mp4')
    deadline = time.monotonic() + 120
    received = set()
    with log.open() as stream:
        while time.monotonic() < deadline:
            position = stream.tell()
            line = stream.readline()
            if not line.endswith('\n'):
                stream.seek(position)
                time.sleep(.1)
                continue
            if line.startswith('STORE_ASSET:'):
                payload = json.loads(line[len('STORE_ASSET:'):])
                filename = payload['filename']
                if Path(filename).name != filename:
                    raise RuntimeError('Capture filename must be a single component')
                (destination / filename).write_bytes(base64.b64decode(payload['data'], validate=True))
                received.add(filename)
                print(f'{language}/{filename}', flush=True)
                if required.issubset(received):
                    break
            elif line.startswith('STORE_CAPTURE_FAILED:'):
                raise RuntimeError(line.strip())
            elif line.startswith('STORE_CAPTURE_COMPLETE'):
                break
    if not required.issubset(received):
        raise RuntimeError(f'Incomplete capture: {sorted(required - received)}; see {errors}')
